/* ─── Executive Dashboard — Dark Theme ─── */
/* ─── Dashboard Shell ─── */
.exec-dashboard {
  min-height: 100vh;
  background: #0a0e14;
  color: #e2e8f0;
  font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif;
}

.exec-dashboard__content {
  padding: 24px;
  max-width: 1440px;
  margin: 0 auto;
}

/* ─── Alert Banner ─── */
.exec-alert-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 24px;
  background: rgba(239, 68, 68, 0.06);
  border-left: 3px solid #ef4444;
}

.exec-alert-banner__left {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: #fca5a5;
}

.exec-alert-banner__label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #64748b;
  text-transform: uppercase;
}

/* ─── Page Header ─── */
.exec-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 24px;
}

.exec-page-header__title {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 4px 0;
  color: #e2e8f0;
}

.exec-page-header__subtitle {
  font-size: 14px;
  color: #64748b;
  margin: 0;
}

.exec-page-header__right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.exec-page-header__live-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #94a3b8;
  background: rgba(34, 197, 94, 0.06);
  border: 1px solid rgba(34, 197, 94, 0.2);
  border-radius: 20px;
  padding: 5px 14px;
}

.exec-page-header__live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  animation: pulse-glow 2s infinite;
}

@keyframes pulse-glow {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
.exec-page-header__warn-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #fca5a5;
  background: rgba(239, 68, 68, 0.06);
  border: 1px solid rgba(239, 68, 68, 0.2);
  border-radius: 20px;
  padding: 5px 14px;
}

/* ─── KPI Row ─── */
.exec-kpi-row {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

/* ─── KPI Card ─── */
.exec-kpi-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.exec-kpi-card--pulse {
  align-items: center;
  justify-content: center;
  padding: 24px 20px;
}

.exec-kpi-card__label {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  margin-bottom: 12px;
}

.exec-kpi-card__ring {
  margin: 4px 0 12px;
}

.exec-kpi-card__ring-score {
  font-size: 28px;
  font-weight: 700;
  fill: #e2e8f0;
  font-variant-numeric: tabular-nums;
}

.exec-kpi-card__ring-sub {
  font-size: 12px;
  fill: #64748b;
}

.exec-kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  color: #e2e8f0;
  font-variant-numeric: tabular-nums;
  margin-bottom: auto;
  padding-bottom: 12px;
}

.exec-kpi-card__value--red {
  color: #ef4444;
}

.exec-kpi-card__caption {
  font-size: 11px;
  color: #64748b;
  margin: 0;
  line-height: 1.5;
}

.exec-kpi-card__caption-trend--red {
  color: #ef4444;
  font-weight: 600;
}

.exec-kpi-card__caption-trend--amber {
  color: #f59e0b;
  font-weight: 600;
}

.exec-kpi-card__caption-trend--green {
  color: #22c55e;
  font-weight: 600;
}

/* ─── Two-Column Layout ─── */
.exec-dashboard__two-col {
  display: grid;
  grid-template-columns: 65fr 35fr;
  gap: 16px;
  margin-bottom: 24px;
}

/* ─── Generic Card ─── */
.exec-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
}

.exec-card--full {
  margin-bottom: 24px;
}

.exec-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}

.exec-card__title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
  margin: 0 0 4px 0;
}

.exec-card__subtitle {
  font-size: 12px;
  color: #64748b;
  margin: 0;
}

.exec-card__badge {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
  flex-shrink: 0;
  white-space: nowrap;
}

.exec-card__badge--red {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.08);
  border: 1px solid rgba(239, 68, 68, 0.2);
}

/* ─── SVG Line Chart ─── */
.exec-chart-svg {
  display: block;
  width: 100%;
}

.exec-chart__axis-text {
  font-size: 10px;
  fill: #475569;
}

.exec-chart__legend {
  display: flex;
  gap: 20px;
  margin-top: 14px;
}

.exec-chart__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
}

.exec-chart__legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.exec-chart__legend-dot--blue {
  background: #3b82f6;
}

.exec-chart__legend-dot--green {
  background: #22c55e;
}

/* ─── Red Alerts List ─── */
.exec-alerts-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.exec-alert-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.12s ease;
}

.exec-alert-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.exec-alert-row__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #ef4444;
  flex-shrink: 0;
  margin-top: 5px;
}

.exec-alert-row__body {
  flex: 1;
  min-width: 0;
}

.exec-alert-row__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.exec-alert-row__title {
  font-size: 13px;
  font-weight: 600;
  color: #e2e8f0;
}

.exec-alert-row__id {
  font-size: 10px;
  font-family: "SF Mono", "Fira Code", monospace;
  color: #64748b;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid #1a2035;
  border-radius: 4px;
  padding: 1px 6px;
  white-space: nowrap;
}

.exec-alert-row__desc {
  font-size: 11px;
  color: #64748b;
  margin: 0 0 2px 0;
  line-height: 1.4;
}

.exec-alert-row__time {
  font-size: 10px;
  color: #475569;
}

.exec-alert-row__chevron {
  color: #475569;
  font-size: 14px;
  flex-shrink: 0;
  margin-top: 2px;
}

/* ─── City Bar Chart ─── */
.exec-bar-chart {
  display: flex;
  gap: 8px;
  height: 200px;
}

.exec-bar-chart__y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 0 4px 24px 0;
}

.exec-bar-chart__y-label {
  font-size: 10px;
  color: #475569;
  text-align: right;
  width: 28px;
}

.exec-bar-chart__bars {
  display: flex;
  flex: 1;
  align-items: flex-end;
  gap: 6px;
  padding-bottom: 24px;
  border-bottom: 1px solid #1a2035;
}

.exec-bar-chart__col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.exec-bar-chart__bar-wrap {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.exec-bar-chart__bar {
  width: 65%;
  background: #3b82f6;
  border-radius: 3px 3px 0 0;
  min-height: 4px;
  transition: background 0.12s ease;
}

.exec-bar-chart__bar:hover {
  background: #60a5fa;
}

.exec-bar-chart__x-label {
  font-size: 9px;
  color: #475569;
  margin-top: 8px;
  text-align: center;
  white-space: nowrap;
}

/* ─── Worst Stores List ─── */
.exec-stores-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.exec-store-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.12s ease;
}

.exec-store-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.exec-store-row__body {
  flex: 1;
  min-width: 0;
}

.exec-store-row__name {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #e2e8f0;
  margin-bottom: 2px;
}

.exec-store-row__info {
  font-size: 11px;
  color: #64748b;
}

.exec-store-row__score-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex-shrink: 0;
}

.exec-store-row__score {
  font-size: 22px;
  font-weight: 700;
  color: #ef4444;
  font-variant-numeric: tabular-nums;
}

.exec-store-row__trend {
  font-size: 10px;
  color: #ef4444;
}

.exec-store-row__chevron {
  color: #475569;
  font-size: 14px;
  flex-shrink: 0;
}

/* ─── Heatmap ─── */
.exec-heatmap__legend {
  display: flex;
  gap: 16px;
  align-items: center;
}

.exec-heatmap__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
}

.exec-heatmap__swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
}

.exec-heatmap__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.exec-heatmap__col {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.exec-heatmap__row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.exec-heatmap__city {
  font-size: 12px;
  color: #64748b;
  width: 90px;
  flex-shrink: 0;
  text-align: right;
}

.exec-heatmap__cells {
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
}

.exec-heatmap__cell {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.exec-heatmap__cell:hover {
  transform: scale(1.5);
  box-shadow: 0 0 6px rgba(255, 255, 255, 0.15);
}

/* ─── Responsive ─── */
@media (max-width: 1200px) {
  .exec-kpi-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .exec-dashboard__two-col {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 768px) {
  .exec-kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .exec-heatmap__grid {
    grid-template-columns: 1fr;
  }
  .exec-page-header {
    flex-direction: column;
    gap: 12px;
  }
